1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface ClaimStep {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	}
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export interface Customer {
27	  yearsWithMHPCO: number;
28	}
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export interface ScenarioResults {
45	  results: (QuoteResult | ClaimResult)[];
46	}
47	
48	const sumBy = <T>(items: T[], amountOf: (item: T) => number): number =>
49	  items.reduce((total, item) => total + amountOf(item), 0);
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	} as const satisfies Record<string, number>;
62	
63	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
64	
65	const basePremiumForType = (type: string): number =>
66	  BASE_PREMIUMS[type as InsurableItemType];
67	
68	const BLOCK_SIZE = 3;
69	const BLOCK_PREMIUM = 60;
70	
71	// Items of one type, quoted together. A group of exactly 3 forms a building
72	// block and is offered at a flat base premium; any other size is priced per
73	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
74	// groups, so neither is a block.
75	type AlikeGroup = [type: string, items: Item[]];
76	
77	const intoAlikeGroups = (items: Item[]): AlikeGroup[] => {
78	  const groups = new Map<string, Item[]>();
79	  for (const item of items) {
80	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
81	  }
82	  return [...groups];
83	};
84	
85	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
86	  items.length === BLOCK_SIZE;
87	
88	const basePremiumForGroup = (group: AlikeGroup): number => {
89	  const [type, items] = group;
90	  return isBuildingBlock(group)
91	    ? BLOCK_PREMIUM
92	    : items.length * basePremiumForType(type);
93	};
94	
95	const sumBasePremiums = (items: Item[]): number =>
96	  sumBy(intoAlikeGroups(items), basePremiumForGroup);
97	
98	const CURSE_SURCHARGE_RATE = 0.5;
99	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
100	const HIGH_ENCHANTMENT_THRESHOLD = 5;
101	
102	const isHighlyEnchanted = (item: Item): boolean =>
103	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
104	
105	// Item-specific modifiers apply to the base premium of the affected item, not
106	// to the policy total.
107	const surchargeRateForItem = (item: Item): number =>
108	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
109	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
110	
111	// Surcharges are charged against the item's own base premium, ignoring any
112	// building-block discount the item may be part of.
113	const surchargeForItem = (item: Item): number =>
114	  basePremiumForType(item.type) * surchargeRateForItem(item);
115	
116	const sumItemSurcharges = (items: Item[]): number =>
117	  sumBy(items, surchargeForItem);
118	
119	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
120	// rounded, intermediate amounts stay fractional.
121	const roundInMHPCOsFavour = Math.ceil;
122	
123	const LOYALTY_DISCOUNT_RATE = 0.2;
124	const LOYALTY_YEARS_THRESHOLD = 2;
125	
126	const isLoyal = (customer: Customer): boolean =>
127	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
128	
129	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
130	
131	// Policy-wide modifiers are summed into one net rate, not compounded. The net
132	// is signed: a loyal customer's discount can outweigh the surcharge.
133	//
134	// The first insurance surcharge applies to every quote — each item in a quote
135	// is treated as a first insurance, regardless of customer history — so it is
136	// not cancelled by the follow-up contract discount.
137	const policyModifierRateFor = (
138	  customer: Customer,
139	  precedingContracts: number,
140	): number =>
141	  FIRST_INSURANCE_SURCHARGE_RATE -
142	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
143	  (precedingContracts > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
144	
145	// Charged against the policy base premium — the sum of all item base premiums —
146	// and added to it, mirroring how surchargeForItem works per item.
147	const policyModifierFor = (
148	  basePremium: number,
149	  customer: Customer,
150	  precedingContracts: number,
151	): number => basePremium * policyModifierRateFor(customer, precedingContracts);
152	
153	const quotePremium = (
154	  items: Item[],
155	  customer: Customer,
156	  precedingContracts: number,
157	): number => {
158	  const basePremium = sumBasePremiums(items);
159	  const itemSurcharges = sumItemSurcharges(items);
160	  const policyModifier = policyModifierFor(
161	    basePremium,
162	    customer,
163	    precedingContracts,
164	  );
165	  return roundInMHPCOsFavour(
166	    basePremium + itemSurcharges + policyModifier + PROCESSING_FEE,
167	  );
168	};
169	
170	// An item's insured worth, distinct from what it costs to insure.
171	const INSURANCE_VALUES = {
172	  sword: 1000,
173	  amulet: 600,
174	  staff: 800,
175	  potion: 400,
176	  rune: 250,
177	  moonstone: 250,
178	} as const satisfies Record<InsurableItemType, number>;
179	
180	const insuranceValueForType = (type: string): number =>
181	  INSURANCE_VALUES[type as InsurableItemType];
182	
183	const DEDUCTIBLE = 100;
184	const CAP_MULTIPLE = 2;
185	
186	// A quote step creates a policy; later claim steps refer to it by that step's
187	// index. The cap is consumed as claims are paid.
188	interface Policy {
189	  items: Item[];
190	  remainingCap: number;
191	}
192	
193	// The policy's total insured worth.
194	const insuranceSumFor = (items: Item[]): number =>
195	  sumBy(items, (item) => insuranceValueForType(item.type));
196	
197	// The most the policy will ever pay out, derived from the plain item values.
198	// Nothing that moves the premium moves the cap: item surcharges cannot inflate
199	// it, and the building-block discount cannot deflate it.
200	const capFor = (items: Item[]): number =>
201	  CAP_MULTIPLE * insuranceSumFor(items);
202	
203	const openPolicy = (items: Item[]): Policy => ({
204	  items,
205	  remainingCap: capFor(items),
206	});
207	
208	// Claims use their own, higher enchantment threshold — unrelated to the
209	// premium-side high-enchantment surcharge.
210	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
211	const HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
212	const FULL_REIMBURSEMENT_RATE = 1;
213	
214	const isHeavilyEnchanted = (item: Item): boolean =>
215	  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
216	
217	// Damage to a heavily enchanted item is only half reimbursed.
218	//
219	// The spec's dragon-material clause is deliberately absent, not forgotten: it
220	// grants full reimbursement, which is already the default, and the heavy
221	// enchantment rule overrides it where both apply. No input exists for which
222	// reading `material` would change the payout, so a branch on it would be dead
223	// code. Reinstate one only if a rule makes dragon material differ from the
224	// default.
225	const reimbursementRateFor = (item: Item): number =>
226	  isHeavilyEnchanted(item)
227	    ? HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE
228	    : FULL_REIMBURSEMENT_RATE;
229	
230	// Each damage entry is charged against one insured item, which no later entry
231	// may reuse — two sword damages need two insured swords. `unclaimed` is drained
232	// as entries are matched.
233	const claimInsuredItem = (unclaimed: Item[], damage: Damage): Item => {
234	  const at = unclaimed.findIndex((item) => item.type === damage.itemType);
235	  if (at === -1) {
236	    throw new Error(
237	      `the policy does not cover a ${damage.itemType} for this damage`,
238	    );
239	  }
240	  return unclaimed.splice(at, 1)[0];
241	};
242	
243	// The reimbursement rate applies to the damage first; the deductible comes off
244	// what remains, once per damage event rather than once per claim.
245	const payoutForDamage = (item: Item, damage: Damage): number =>
246	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
247	
248	// Settling a claim consumes the policy's cap, so the policy carries less cover
249	// into the next claim. Kept separate from settleClaim so the state change is
250	// visible where the policy is held rather than hidden behind a pure-looking call.
251	const consumeCap = (policy: Policy, result: ClaimResult): Policy => ({
252	  ...policy,
253	  remainingCap: result.remainingCap,
254	});
255	
256	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
257	  const unclaimed = [...policy.items];
258	  const payout = sumBy(damages, (damage) =>
259	    payoutForDamage(claimInsuredItem(unclaimed, damage), damage),
260	  );
261	  return { payout, remainingCap: policy.remainingCap - payout };
262	};
263	
264	const runStep = (
265	  step: Step,
266	  customer: Customer,
267	  precedingContracts: number,
268	  policies: Map<number, Policy>,
269	  stepIndex: number,
270	): QuoteResult | ClaimResult => {
271	  switch (step.op) {
272	    case "quote":
273	      policies.set(stepIndex, openPolicy(step.items));
274	      return { premium: quotePremium(step.items, customer, precedingContracts) };
275	    case "claim": {
276	      const policy = policies.get(step.policy)!;
277	      const result = settleClaim(policy, step.incident.damages);
278	      policies.set(step.policy, consumeCap(policy, result));
279	      return result;
280	    }
281	  }
282	};
283	
284	// Each quote in a scenario forms a contract, so every quote after the first is
285	// a follow-up. Steps are run in order and a step sees only the contracts that
286	// precede it. Only quote steps create contracts.
287	export const runScenario = (scenario: Scenario): ScenarioResults => {
288	  const results: (QuoteResult | ClaimResult)[] = [];
289	  const policies = new Map<number, Policy>();
290	  let contractsSoFar = 0;
291	  scenario.steps.forEach((step, stepIndex) => {
292	    results.push(
293	      runStep(step, scenario.customer, contractsSoFar, policies, stepIndex),
294	    );
295	    if (step.op === "quote") contractsSoFar += 1;
296	  });
297	  return { results };
298	};
